/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// </summary>
[ExtensionOf(tableStr(TAMRebateDateTrans))]
final class METTAMRebateDateTransTbl_Extension
{
}

Method.Source:
/// <summary>
/// when TAMRebateDateTrans deletes the underlying TAMRebateTrans, also unmark the METRebateScanSupplierTable records
/// </summary>
public void delete()
{
    ttsbegin;

    // Update external sales data provision or rebate processed to No
    METRebateScanSupplierTable::updateProcessedFlags(this.RebateTransactionType, NoYes::No, this.RebateTransId);

    next delete();

    ttscommit;
}
